#include <iostream>
#include <memory>
#include <utility>
struct Resource {
    static inline int live = 0;
    Resource() { ++live; }
    ~Resource() { --live; }
};
int main() {
    std::cout << "before=" << Resource::live << '\n';
    {
        auto first = std::make_unique<Resource>();
        auto second = std::move(first); // Transfer the one owning handle.
        std::cout << std::boolalpha << "first=" << bool(first)
                  << " second=" << bool(second) << " live=" << Resource::live << '\n';
    }
    std::cout << "after=" << Resource::live << '\n';
}

#include <cstddef>
#include <iostream>
#include <limits>
int main() {
    const std::size_t extent = 8;
    const auto offset = std::numeric_limits<std::size_t>::max() - 2;
    const std::size_t length = 5;
    const bool naive = offset + length <= extent;
    const bool guarded = offset <= extent && length <= extent - offset;
    std::cout << std::boolalpha << "naive=" << naive
              << " guarded=" << guarded << '\n';
}

