// LAB: Check a copy before touching the destination
// Copy a source string into an existing character array only if the characters and trailing null fit. Return false without writing anything when the capacity is too small.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>
#include <stdexcept>
#include <vector>

int main() {
    const std::vector<int> values{8, 9, 10};
    try {
        std::cout << values.at(3) << '\n';
    } catch (const std::out_of_range&) {
        std::cout << "out of range\n";
    }
    assert(values.size() == 3);
}

#include <algorithm>
#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <string>

bool copy_text(char* destination, std::size_t capacity, const std::string& source) {
    if(capacity == 0 || source.size() >= capacity) return false;
    std::copy(source.begin(),source.end(),destination);
    destination[source.size()] = '\0';
    return true;
}

int main() {
    std::array<char,4> destination{'x','x','x','x'};
    const auto before = destination;
    assert(!copy_text(destination.data(),3,"cat") && destination == before);
    assert(copy_text(destination.data(),4,"cat"));
    assert(std::string(destination.data()) == "cat");
    std::array<char,1> empty{'x'};
    assert(copy_text(empty.data(),1,"") && empty[0] == '\0');
    assert(!copy_text(nullptr,0,""));
    std::cout << destination.data() << " rejected=unchanged\n";
}

